-- A single (U)Int512 key, nullable or not, in IN / DISTINCT / GROUP BY / JOIN (hash and parallel_hash). It used to
-- throw LOGICAL_ERROR ("Numeric column has sizeOfField not in 1, 2, 4, 8, 16, 32") in sets and joins.
SELECT 'Int512 IN', count() FROM (SELECT CAST(number AS Int512) AS k FROM numbers(100)) WHERE k IN (SELECT CAST(number * 2 AS Int512) FROM numbers(50));
SELECT 'Int512 DISTINCT', count() FROM (SELECT DISTINCT CAST(number % 7 AS Int512) AS k FROM numbers(100));
SELECT 'Int512 GROUP BY', count() FROM (SELECT CAST(number % 7 AS Int512) AS k FROM numbers(100) GROUP BY k);
SELECT 'Int512 JOIN hash', count() FROM (SELECT CAST(number AS Int512) AS k FROM numbers(100)) AS l INNER JOIN (SELECT CAST(number * 2 AS Int512) AS k FROM numbers(50)) AS r USING (k) SETTINGS join_algorithm = 'hash';
SELECT 'Int512 JOIN parallel_hash', count() FROM (SELECT CAST(number AS Int512) AS k FROM numbers(100)) AS l INNER JOIN (SELECT CAST(number * 2 AS Int512) AS k FROM numbers(50)) AS r USING (k) SETTINGS join_algorithm = 'parallel_hash';
SELECT 'UInt512 IN', count() FROM (SELECT CAST(number AS UInt512) AS k FROM numbers(100)) WHERE k IN (SELECT CAST(number * 2 AS UInt512) FROM numbers(50));
SELECT 'UInt512 DISTINCT', count() FROM (SELECT DISTINCT CAST(number % 7 AS UInt512) AS k FROM numbers(100));
SELECT 'UInt512 GROUP BY', count() FROM (SELECT CAST(number % 7 AS UInt512) AS k FROM numbers(100) GROUP BY k);
SELECT 'UInt512 JOIN hash', count() FROM (SELECT CAST(number AS UInt512) AS k FROM numbers(100)) AS l INNER JOIN (SELECT CAST(number * 2 AS UInt512) AS k FROM numbers(50)) AS r USING (k) SETTINGS join_algorithm = 'hash';
SELECT 'UInt512 JOIN parallel_hash', count() FROM (SELECT CAST(number AS UInt512) AS k FROM numbers(100)) AS l INNER JOIN (SELECT CAST(number * 2 AS UInt512) AS k FROM numbers(50)) AS r USING (k) SETTINGS join_algorithm = 'parallel_hash';
SELECT 'Nullable(Int512) IN', count() FROM (SELECT CAST(number AS Nullable(Int512)) AS k FROM numbers(100)) WHERE k IN (SELECT CAST(number * 2 AS Nullable(Int512)) FROM numbers(50));
SELECT 'Nullable(Int512) DISTINCT', count() FROM (SELECT DISTINCT CAST(number % 7 AS Nullable(Int512)) AS k FROM numbers(100));
SELECT 'Nullable(Int512) GROUP BY', count() FROM (SELECT CAST(number % 7 AS Nullable(Int512)) AS k FROM numbers(100) GROUP BY k);
SELECT 'Nullable(Int512) JOIN hash', count() FROM (SELECT CAST(number AS Nullable(Int512)) AS k FROM numbers(100)) AS l INNER JOIN (SELECT CAST(number * 2 AS Nullable(Int512)) AS k FROM numbers(50)) AS r USING (k) SETTINGS join_algorithm = 'hash';
SELECT 'Nullable(Int512) JOIN parallel_hash', count() FROM (SELECT CAST(number AS Nullable(Int512)) AS k FROM numbers(100)) AS l INNER JOIN (SELECT CAST(number * 2 AS Nullable(Int512)) AS k FROM numbers(50)) AS r USING (k) SETTINGS join_algorithm = 'parallel_hash';
SELECT 'Nullable(UInt512) IN', count() FROM (SELECT CAST(number AS Nullable(UInt512)) AS k FROM numbers(100)) WHERE k IN (SELECT CAST(number * 2 AS Nullable(UInt512)) FROM numbers(50));
SELECT 'Nullable(UInt512) DISTINCT', count() FROM (SELECT DISTINCT CAST(number % 7 AS Nullable(UInt512)) AS k FROM numbers(100));
SELECT 'Nullable(UInt512) GROUP BY', count() FROM (SELECT CAST(number % 7 AS Nullable(UInt512)) AS k FROM numbers(100) GROUP BY k);
SELECT 'Nullable(UInt512) JOIN hash', count() FROM (SELECT CAST(number AS Nullable(UInt512)) AS k FROM numbers(100)) AS l INNER JOIN (SELECT CAST(number * 2 AS Nullable(UInt512)) AS k FROM numbers(50)) AS r USING (k) SETTINGS join_algorithm = 'hash';
SELECT 'Nullable(UInt512) JOIN parallel_hash', count() FROM (SELECT CAST(number AS Nullable(UInt512)) AS k FROM numbers(100)) AS l INNER JOIN (SELECT CAST(number * 2 AS Nullable(UInt512)) AS k FROM numbers(50)) AS r USING (k) SETTINGS join_algorithm = 'parallel_hash';
SELECT count() FROM (SELECT DISTINCT k FROM values('k Int512', ('-6703903964971298549787012499102923063739682910296196688861780721860882015036773488400937149083451713845015929093243025426876941405973284973216824503042048'), ('6703903964971298549787012499102923063739682910296196688861780721860882015036773488400937149083451713845015929093243025426876941405973284973216824503042047'), (0), (-1), (0)));
SELECT k FROM values('k Int512', ('-6703903964971298549787012499102923063739682910296196688861780721860882015036773488400937149083451713845015929093243025426876941405973284973216824503042048'), ('6703903964971298549787012499102923063739682910296196688861780721860882015036773488400937149083451713845015929093243025426876941405973284973216824503042047'), (0)) WHERE k IN (SELECT arrayJoin([toInt512('-6703903964971298549787012499102923063739682910296196688861780721860882015036773488400937149083451713845015929093243025426876941405973284973216824503042048'), toInt512(0)])) ORDER BY k;
